1	/* ===== Người treo dù: điều phối (src/explore/pilot/index.ts) =====
2	   Gắn / cập nhật / gỡ nhân vật có xương dưới mỗi dù (của mình lẫn người khác), spec §4, §7:
3	   - plPreload(): bắt đầu nạp pilot.glb (thẻ Dù lượn, explore.start / startWatching). Trang thường không gọi nên không tải.
4	   - plUpdate(): gọi từ exPlaceGlider mỗi khung. Nguồn chưa về / lỗi → giữ hình 'full' (người khối). Nguồn đã về và dù đang hiện → gắn trong vòng khung:
5	     mesh cánh đổi sang hình 'canopy', thêm nhóm con ex-pilot (rig.ts). Dù đang ẩn lúc nguồn về thì chưa gắn (Review Focus 1).
6	   - Tín hiệu (react.ts plSignals) từ vị trí + bank của chính dù nên dùng chung cho dù của mình, dù người khác, chế độ xem; gió đọc weatherU (cùng nguồn cây / mưa).
7	   - `?pilot=off` ép hình khối; group.userData.plOff = true (remote.ts: dù người khác khi pilot.remote = false hoặc điện thoại) cũng giữ hình khối.
8	   Không cấp phát mỗi khung (trừ lần gắn). */
9	import * as THREE from 'three';
10	import { CONFIG } from '../../config';
11	import { weatherU } from '../../core/shared';
12	import { exGliderGeometry } from '../glider';
13	import type { GliderState } from '../flight';
14	import { plSignals, type PlPose, type PlSignals, type PlTrack } from './react';
15	import { PlRig } from './rig';
16	import { plLoad, plSetWarm as plSetWarmLoad, type PlSource } from './load';
17	
18	interface PlEntry { rig: PlRig | null; track: PlTrack; sig: PlSignals; seed: number }
19	
20	const entries = new Map<THREE.Group, PlEntry>();
21	const OFF = typeof location !== 'undefined' && new URLSearchParams(location.search).get('pilot') === 'off';
22	let loader: () => Promise<PlSource | null> = plLoad;
23	let src: PlSource | null | undefined;   // undefined = chưa có kết quả, null = lỗi (giữ hình khối suốt phiên)
24	let asked = false, gen = 0, seeds = 0;
25	
26	/* Nguồn nếu đã nạp xong; chưa thì bắt đầu nạp (một lần) và trả null. Không ném */
27	function need(): PlSource | null {
28	  if (src !== undefined) return src;
29	  if (!asked) {
30	    asked = true;
31	    const g = gen, done = (r: PlSource | null) => { if (g === gen) src = r || null; };
32	    try { loader().then(done, () => done(null)); } catch { done(null); }
33	  }
34	  return null;
35	}
36	
37	/* Mức gió thời tiết 0..1 cho người treo: gió trung bình + giật (m/s, weather/index.ts ghi vào weatherU) chia windRef */
38	function plWind(): number {
39	  const v = (weatherU.uWind.value + weatherU.uGust.value) / CONFIG.explore.pilot.windRef;
40	  return v > 0 ? (v < 1 ? v : 1) : 0;
41	}
42	
43	/* Dựng rig lỗi (mô hình hỏng kiểu gì đó): warn một lần, coi nguồn không dùng được (mọi dù, mọi khung sau giữ hình khối, không thử lại), không ném */
44	function fail(e: unknown): void {
45	  if (src) { console.warn('Dù lượn: dựng người treo lỗi, dùng hình khối', e); src = null; }
46	}
47	
48	function attach(glider: THREE.Group, e: PlEntry, s: PlSource): void {
49	  let rig: PlRig | null = null;
50	  try {
51	    rig = new PlRig(s, e.seed);
52	    glider.add(rig.group);
53	    (glider.children[0] as THREE.Mesh).geometry = exGliderGeometry('canopy');
54	  } catch (err) {
55	    if (rig) { glider.remove(rig.group); try { rig.dispose(); } catch { /* đã lỗi rồi */ } }
56	    (glider.children[0] as THREE.Mesh).geometry = exGliderGeometry('full');
57	    fail(err);
58	    return;
59	  }
60	  e.rig = rig;
61	  e.track.has = false;
62	}
63	
64	export function plPreload(): void { if (!OFF) need(); }
65	
66	export function plUpdate(glider: THREE.Group, s: GliderState, dt: number, turnInput?: number): void {
67	  if (OFF) return;
68	  let e = entries.get(glider);
69	  if (!e) {
70	    if (glider.userData.plOff) return;
71	    e = { rig: null, track: { x: 0, y: 0, z: 0, speed: 0, has: false }, sig: { turn: 0, acc: 0, vy: 0, wind: 0 }, seed: ++seeds };
72	    entries.set(glider, e);
73	  }
74	  if (!e.rig) {
75	    const so = need();
76	    if (!so || !glider.visible) return;
77	    attach(glider, e, so);
78	    if (!e.rig) return;
79	  }
80	  try {
81	    plSignals(e.sig, e.track, s.pos.x, s.pos.y, s.pos.z, s.bank, dt, plWind(), turnInput);
82	    e.rig!.update(e.sig, dt);
83	  } catch (err) {
84	    /* lỗi lúc diễn: trả hình khối cho dù này, không ném về vòng vẽ */
85	    fail(err);
86	    plDetach(glider);
87	  }
88	}
89	
90	/* Dù nhảy vị trí / đổi chủ: lò xo về nghỉ, quên mẫu vị trí (không sinh gia tốc giả) */
91	export function plReset(glider: THREE.Group): void {
92	  const e = entries.get(glider);
93	  if (!e) return;
94	  e.track.has = false; e.track.hasSpeed = false; e.track.acc = 0; e.track.vy = 0;
95	  if (e.rig) e.rig.reset();
96	}
97	
98	/* Gỡ nhân vật: trả hình 'full', dispose rig */
99	export function plDetach(glider: THREE.Group): void {
100	  const e = entries.get(glider);
101	  if (!e) return;
102	  if (e.rig) { e.rig.dispose(); e.rig = null; (glider.children[0] as THREE.Mesh).geometry = exGliderGeometry('full'); }
103	  entries.delete(glider);
104	}
105	
106	export function plSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { plSetWarmLoad(fn); }
107	
108	const ZERO: PlPose = { swingRoll: 0, swingPitch: 0, swingYaw: 0, spineRoll: 0, spinePitch: 0, spineTwist: 0, headYaw: 0, headRoll: 0, legSide: 0, legFore: 0, kneeL: 0, kneeR: 0, legSplit: 0, brakeL: 0, brakeR: 0, packRoll: 0, packPitch: 0, strap: 0 };
109	
110	/* Cho test: real = đang hiện bằng nhân vật có xương; handErr m (điểm nắm ↔ quai phanh, −1 khi chưa có rig); pose bản sao; calls = số lưới đang hiện của dù (mỗi lưới một lệnh vẽ) */
111	export function plDebug(glider: THREE.Group): { real: boolean; handErr: [number, number]; pose: PlPose; calls: number } | null {
112	  const e = entries.get(glider);
113	  let calls = 0;
114	  glider.traverseVisible((o) => { if ((o as THREE.Mesh).isMesh) calls++; });
115	  if (!e) return null;
116	  const r = e.rig;
117	  return { real: !!r && glider.visible, handErr: r ? r.handErr() : [-1, -1], pose: { ...(r ? r.react.pose : ZERO) }, calls };
118	}
119	
120	/* Chỉ dùng trong unit test: thay bộ nạp (null = plLoad thật), quên nguồn và mọi dù đã gắn */
121	export function __plSetLoader(fn: (() => Promise<PlSource | null>) | null): void {
122	  loader = fn || plLoad; gen++;
123	  src = undefined; asked = false;
124	  for (const g of [...entries.keys()]) plDetach(g);
125	}
126

