1	/* ===== Người treo dù: nạp mô hình nhân vật có xương (public/people/pilot.glb) (src/explore/pilot/load.ts) =====
2	   - plLoad(): import() động GLTFLoader + SkeletonUtils (chunk riêng, trang thường không tải; cùng chunk với Đi dạo), nạp pilot.glb một lần trong phiên.
3	     Lỗi bất kỳ (mạng, tệp hỏng, thiếu đoạn `sit`, thiếu xương bắt buộc) hoặc quá CONFIG.explore.pilot.loadMs → console.warn một lần, trả null,
4	     không thử lại; promise không bao giờ bị từ chối. Về muộn sau khi đã quá giờ thì bỏ (giữ hình khối suốt phiên, spec §7).
5	   - plSource(): chuẩn hóa cảnh đã nạp: lớp 1 (không vào phản chiếu nước), không đổ / nhận bóng, tắt frustumCulled (hộp bao theo tư thế gốc sai khi diễn).
6	     KHÁC Đi dạo: giữ normalMap và roughnessMap (kênh G của ORM) của glb, không ghi đè độ nhám bằng hằng số.
7	   - Làm nóng shader (D-018): sau khi nạp, chờ hàm do plSetWarm gắn (compileAsync theo cảnh chính, ≤ pilot.warmMs) rồi mới trả nguồn. Thiết kế: spec §4, §7. */
8	import * as THREE from 'three';
9	import { CONFIG } from '../../config';
10	import { plBonesMissing } from './bones';
11	import { plGearWarmObject } from './gear';
12	
13	export interface PlSource {
14	  scene: THREE.Object3D;                          // cảnh gốc (không thêm vào scene; chỉ để sao chép)
15	  clip: THREE.AnimationClip;                      // đoạn `sit` (tư thế nền có nhịp thở)
16	  clone: (o: THREE.Object3D) => THREE.Object3D;   // SkeletonUtils.clone (test truyền bản giả)
17	}
18	
19	/* Chuẩn hóa cảnh + đoạn đã nạp thành nguồn dùng chung. Thiếu `sit` hoặc thiếu xương bắt buộc thì ném (plLoad bắt, trả null) */
20	export function plSource(scene: THREE.Object3D, clips: THREE.AnimationClip[], clone: (o: THREE.Object3D) => THREE.Object3D): PlSource {
21	  const clip = clips.find((c) => c.name === 'sit');
22	  if (!clip) throw new Error('thiếu đoạn sit');
23	  const miss = plBonesMissing(scene);
24	  if (miss.length) throw new Error('thiếu xương ' + miss.join(', '));
25	  scene.traverse((o) => {
26	    o.layers.set(1);
27	    const m = o as THREE.Mesh;
28	    if (!m.isMesh) return;
29	    m.castShadow = false; m.receiveShadow = false; m.frustumCulled = false;
30	    const mats = Array.isArray(m.material) ? m.material : [m.material];
31	    for (const mat of mats) if (mat.alphaTest > 0) mat.transparent = false;   // mảnh alpha (nếu có): cắt theo alphaTest, không trộn trong suốt
32	  });
33	  return { scene, clip, clone };
34	}
35	
36	/* Làm nóng shader: explore/index.ts gắn hàm biên dịch sẵn (load.ts không import renderer để chạy được trong unit test) */
37	let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
38	export function plSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
39	async function plWarm(o: THREE.Object3D): Promise<void> {
40	  if (!warm) return;
41	  let timer = 0;
42	  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, CONFIG.explore.pilot.warmMs) as unknown as number; })]); }
43	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch như cũ */ }
44	  finally { clearTimeout(timer); }
45	}
46	
47	let cache: Promise<PlSource | null> | null = null;
48	/* Chỉ dùng trong unit test: thay bước tải thô (null = tải thật) và quên kết quả nhớ đệm */
49	let raw: (() => Promise<{ scene: THREE.Object3D; animations: THREE.AnimationClip[]; clone: PlSource['clone'] }>) | null = null;
50	export function __plSetRawLoad(fn: typeof raw): void { raw = fn; cache = null; }
51	
52	/* Nạp một lần (nhớ đệm). Không bao giờ ném / từ chối: lỗi hoặc quá giờ → warn một lần, null */
53	export function plLoad(): Promise<PlSource | null> {
54	  if (cache) return cache;
55	  const P = CONFIG.explore.pilot;
56	  const work = (async (): Promise<PlSource | null> => {
57	    let gltf: { scene: THREE.Object3D; animations: THREE.AnimationClip[] }, clone: PlSource['clone'];
58	    if (raw) { const r = await raw(); gltf = r; clone = r.clone; }
59	    else {
60	      const [{ GLTFLoader }, SU] = await Promise.all([import('three/addons/loaders/GLTFLoader.js'), import('three/addons/utils/SkeletonUtils.js')]);
61	      gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + P.model); clone = SU.clone;
62	    }
63	    const src = plSource(gltf.scene, gltf.animations, clone);
64	    const gw = plGearWarmObject();
65	    try { await Promise.all([plWarm(src.scene), plWarm(gw.object)]); } finally { gw.dispose(); }   // cả shader trang bị (lần gắn đầu không biên dịch thêm); nguồn chỉ "sẵn sàng" sau khi shader skinning đã biên dịch: lần hiện đầu không khựng
66	    return src;
67	  })();
68	  let timer = 0;
69	  const late = new Promise<'late'>((r) => { timer = setTimeout(() => r('late'), P.loadMs) as unknown as number; });
70	  cache = Promise.race([work, late]).then((r) => {
71	    clearTimeout(timer);
72	    if (r === 'late') { console.warn('Dù lượn: tải người treo quá giờ, dùng hình khối'); return null; }
73	    return r;
74	  }, (e) => { clearTimeout(timer); console.warn('Dù lượn: không nạp được người treo, dùng hình khối', e); return null; });
75	  work.catch(() => { /* đã quá giờ: lỗi về muộn không còn ai nghe */ });
76	  return cache;
77	}
78

