1	/* ============================ Người treo dù: trang bị bằng code ============================
2	   Một BufferGeometry có xương (skinIndex / skinWeight) cho SkinnedMesh: ghế ngồi + hai má ghế, hộp dù dự phòng dưới ghế + quai kéo đỏ, ba lô / tấm bảo vệ lưng,
3	   đệm thắt lưng, đai vai (lưng → vai → ngực → carabiner), đai ngực có khóa, vòng đai đùi có khóa, carabiner (vòng bầu dục), riser (đai dẹt hai nhánh),
4	   quai phanh (thanh trong nắm tay), dây phanh, dây treo.
5	   Mỗi đỉnh gắn cứng một xương (trọng số 1). Đai và dây nối hai xương là dải có đầu này một xương, đầu kia một xương nên luôn bám người lẫn dù khi xương dịch chuyển.
6	   Hệ tọa độ: hệ group dù (+X bay, +Y lên, +Z phải); mọi bộ phận dựng theo vị trí nghỉ của xương truyền vào (PlGearRest, rig.ts đo ở tư thế bay nền), không có số tuyệt đối.
7	   Khối đệm là siêu elip (bo tròn, pháp tuyến mượt); đặt trong "hệ thân": trục a dọc thân (hông → Spine2), b ra trước vuông góc a, c = +Z.
8	   Thuần BufferGeometry, không cần DOM nên test node dùng được. Thông số: CONFIG.explore.pilot.gear. Trần 6 000 tam giác (test kiểm). */
9	import * as THREE from 'three';
10	import { CONFIG } from '../../config';
11	import { exLineTops, exBrakeTops } from '../glider';
12	
13	/* Thứ tự xương = giá trị skinIndex. 'wing' là gốc cánh (đầu trên của dây), 'hang' là đỉnh riser (tâm lắc), 'pack' là ba lô lệch pha với thân */
14	export const PL_GEAR_BONES = ['wing', 'hang', 'pelvis', 'spine', 'handL', 'handR', 'thighL', 'thighR', 'pack'] as const;
15	/* Đoạn đỉnh của một dây trong geometry: kind 'line' (dây treo) hoặc 'brake' (dây phanh chính quai → điểm tụ); ba / bb = xương hai đầu; geometry.userData.spans */
16	export interface PlGearSpan { kind: 'line' | 'brake'; ba: number; bb: number; start: number; count: number }
17	export interface PlGearRest {
18	  hang: number[]; pelvis: number[]; spine: number[]; handL: number[]; handR: number[]; thighL: number[]; thighR: number[];   // vị trí nghỉ trong hệ group dù, m (hang: giữa hai carabiner ở exHangY, KHÁC xương `hang` của trang bị là đỉnh riser; spine: Spine2)
19	  kneeL?: number[]; kneeR?: number[];   // m — gối (đầu xương cẳng chân); thiếu thì đùi + CONFIG.explore.pilot.gear.thigh.kneeFb về trước
20	  gripL?: number[]; gripR?: number[];   // m — điểm nắm quai phanh (giữa nắm tay); thiếu thì lấy vị trí xương bàn tay
21	  barL?: number[]; barR?: number[];     // hướng đơn vị của thanh quai phanh (ngang lòng bàn tay); thiếu thì +Z
22	  fingL?: number[]; fingR?: number[];   // hướng đơn vị từ cổ tay ra ngón; thiếu thì +Y
23	}
24	
25	const PG = CONFIG.explore.pilot, GC = PG.gear;
26	const BI = (n: typeof PL_GEAR_BONES[number]): number => PL_GEAR_BONES.indexOf(n);
27	const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
28	const VA = (a: number[]) => new THREE.Vector3(a[0], a[1], a[2]);
29	const COL = (hex: string): number[] => { const c = new THREE.Color(hex); return [c.r, c.g, c.b]; };
30	/* Số đoạn chia hình học (độ mịn, không phải số đo thật): (vĩ, kinh) từng khối đệm, đoạn của carabiner và vòng đai đùi */
31	const SEG = { seat: [6, 12], side: [5, 10], reserve: [5, 10], handle: [3, 6], lumbar: [5, 10], back: [8, 14], buckle: [3, 6], carab: 12, thigh: 14 };
32	const spow = (v: number, e: number): number => Math.sign(v) * Math.pow(Math.abs(v), e);
33	
34	/* Bộ gom đỉnh không chỉ số: mỗi tam giác có màu và xương theo đỉnh; pháp tuyến phẳng hoặc truyền vào */
35	class GearBuf {
36	  pos: number[] = []; nor: number[] = []; col: number[] = []; si: number[] = [];
37	  spans: PlGearSpan[] = [];   // đoạn đỉnh của từng dây (test dùng để kiểm hai đầu hai xương)
38	  span(kind: PlGearSpan['kind'], ba: number, bb: number, f: () => void): void {
39	    const start = this.si.length; f(); this.spans.push({ kind, ba, bb, start, count: this.si.length - start });
40	  }
41	  /* Một tam giác; ba xương theo ba đỉnh; ns: pháp tuyến từng đỉnh (bỏ trống = phẳng) */
42	  tri(a: THREE.Vector3, b: THREE.Vector3, c: THREE.Vector3, ba: number, bb: number, bc: number, rgb: number[], ns?: THREE.Vector3[]): void {
43	    const n = b.clone().sub(a).cross(c.clone().sub(a));
44	    if (n.lengthSq() < 1e-14) return;
45	    n.normalize();
46	    const pts: [THREE.Vector3, number][] = [[a, ba], [b, bb], [c, bc]];
47	    for (let i = 0; i < 3; i++) {
48	      const [p, bone] = pts[i], nn = ns ? ns[i] : n;
49	      this.pos.push(p.x, p.y, p.z); this.nor.push(nn.x, nn.y, nn.z); this.col.push(rgb[0], rgb[1], rgb[2]); this.si.push(bone);
50	    }
51	  }
52	  /* Mặt bốn đỉnh; ref nằm bên trong khối, mặt luôn quay ra xa ref */
53	  quad(p: THREE.Vector3[], bn: number[], rgb: number[], ref: THREE.Vector3): void {
54	    const ctr = p[0].clone().add(p[1]).add(p[2]).add(p[3]).multiplyScalar(0.25);
55	    const n = p[1].clone().sub(p[0]).cross(p[2].clone().sub(p[0]));
56	    const o = n.dot(ctr.sub(ref)) < 0 ? [0, 3, 2, 1] : [0, 1, 2, 3];
57	    this.tri(p[o[0]], p[o[1]], p[o[2]], bn[o[0]], bn[o[1]], bn[o[2]], rgb);
58	    this.tri(p[o[0]], p[o[2]], p[o[3]], bn[o[0]], bn[o[2]], bn[o[3]], rgb);
59	  }
60	  /* Khối đệm siêu elip: tâm c, ba trục đơn vị ax, nửa kích thước h, độ vuông e, chia nu (vĩ) × nv (kinh), một xương */
61	  blob(c: THREE.Vector3, ax: THREE.Vector3[], h: number[], e: number, nu: number, nv: number, bone: number, rgb: number[]): void {
62	    const P: THREE.Vector3[][] = [], N: THREE.Vector3[][] = [];
63	    for (let i = 0; i <= nu; i++) {
64	      const u = -Math.PI / 2 + Math.PI * i / nu, rp: THREE.Vector3[] = [], rn: THREE.Vector3[] = [];
65	      for (let j = 0; j <= nv; j++) {
66	        const v = -Math.PI + 2 * Math.PI * j / nv;
67	        const l = [h[0] * spow(Math.cos(u), e) * spow(Math.cos(v), e), h[1] * spow(Math.cos(u), e) * spow(Math.sin(v), e), h[2] * spow(Math.sin(u), e)];
68	        const n = [spow(Math.cos(u), 2 - e) * spow(Math.cos(v), 2 - e) / h[0], spow(Math.cos(u), 2 - e) * spow(Math.sin(v), 2 - e) / h[1], spow(Math.sin(u), 2 - e) / h[2]];
69	        rp.push(c.clone().addScaledVector(ax[0], l[0]).addScaledVector(ax[1], l[1]).addScaledVector(ax[2], l[2]));
70	        const nn = V(0, 0, 0).addScaledVector(ax[0], n[0]).addScaledVector(ax[1], n[1]).addScaledVector(ax[2], n[2]);
71	        rn.push(nn.lengthSq() > 1e-12 ? nn.normalize() : ax[2].clone().multiplyScalar(Math.sign(l[2]) || 1));
72	      }
73	      P.push(rp); N.push(rn);
74	    }
75	    for (let i = 0; i < nu; i++) for (let j = 0; j < nv; j++) {
76	      const q = [[i, j], [i + 1, j], [i + 1, j + 1], [i, j + 1]];
77	      const g = (k: number) => P[q[k][0]][q[k][1]], gn = (k: number) => N[q[k][0]][q[k][1]];
78	      /* chiều quay mặt theo pháp tuyến giải tích (mặt suy biến ở cực bị tri() bỏ) */
79	      const flip = g(1).clone().sub(g(0)).cross(g(2).clone().sub(g(0))).dot(gn(0).clone().add(gn(2))) < 0
80	        || (g(1).distanceToSquared(g(0)) < 1e-12 && g(2).clone().sub(g(0)).cross(g(3).clone().sub(g(0))).dot(gn(0).clone().add(gn(2))) < 0);
81	      const ts = flip ? [[0, 2, 1], [0, 3, 2]] : [[0, 1, 2], [0, 2, 3]];
82	      for (const t of ts) this.tri(g(t[0]), g(t[1]), g(t[2]), bone, bone, bone, rgb, [gn(t[0]), gn(t[1]), gn(t[2])]);
83	    }
84	  }
85	  /* Dải đai dẹt qua các điểm pts: bề rộng w nằm ngang, bề dày t theo outs (pháp tuyến bề mặt tại từng điểm); bones từng điểm; closed: khép vòng */
86	  band(pts: THREE.Vector3[], outs: THREE.Vector3[], bones: number[], w: number, t: number, rgb: number[], closed = false): void {
87	    const n = pts.length, rings: THREE.Vector3[][] = [];
88	    for (let i = 0; i < n; i++) {
89	      const prev = pts[closed ? (i - 1 + n) % n : Math.max(0, i - 1)], next = pts[closed ? (i + 1) % n : Math.min(n - 1, i + 1)];
90	      const tg = next.clone().sub(prev).normalize(), o = outs[i].clone().addScaledVector(tg, -outs[i].dot(tg));
91	      if (o.lengthSq() < 1e-8) o.copy(Math.abs(tg.y) < 0.9 ? V(0, 1, 0) : V(1, 0, 0)).addScaledVector(tg, -o.dot(tg));
92	      o.normalize();
93	      const sd = tg.clone().cross(o).normalize(), p = pts[i];
94	      rings.push([[1, 1], [-1, 1], [-1, -1], [1, -1]].map(([s, r]) => p.clone().addScaledVector(sd, s * w / 2).addScaledVector(o, r * t / 2)));
95	    }
96	    const segs = closed ? n : n - 1;
97	    for (let i = 0; i < segs; i++) {
98	      const j = (i + 1) % n, ra = rings[i], rb = rings[j], ref = pts[i].clone().add(pts[j]).multiplyScalar(0.5);
99	      for (let k = 0; k < 4; k++) this.quad([ra[k], ra[(k + 1) % 4], rb[(k + 1) % 4], rb[k]], [bones[i], bones[i], bones[j], bones[j]], rgb, ref);
100	    }
101	  }
102	  /* Lăng trụ bốn cạnh từ a tới b (dây): mặt cắt w × t; đáy a xương ba, đáy b xương bb */
103	  prism(a: THREE.Vector3, b: THREE.Vector3, ba: number, bb: number, rgb: number[], w: number, t: number, hint = V(0, 0, 1)): void {
104	    const d = b.clone().sub(a);
105	    if (d.length() < 1e-4) return;
106	    d.normalize();
107	    let u = hint.clone().sub(d.clone().multiplyScalar(hint.dot(d)));
108	    if (u.lengthSq() < 1e-6) u = Math.abs(d.y) < 0.9 ? V(0, 1, 0).sub(d.clone().multiplyScalar(d.y)) : V(1, 0, 0).sub(d.clone().multiplyScalar(d.x));
109	    u.normalize();
110	    const v = d.clone().cross(u).normalize();
111	    const ring = (o: THREE.Vector3) => [[1, 1], [-1, 1], [-1, -1], [1, -1]].map(([s, r]) => o.clone().addScaledVector(u, s * w / 2).addScaledVector(v, r * t / 2));
112	    const ra = ring(a), rb = ring(b), ref = a.clone().add(b).multiplyScalar(0.5);
113	    for (let k = 0; k < 4; k++) this.quad([ra[k], ra[(k + 1) % 4], rb[(k + 1) % 4], rb[k]], [ba, ba, bb, bb], rgb, ref);
114	  }
115	  /* Vòng bầu dục (carabiner) tâm c, mặt phẳng vuông góc nAx, trục dài lAx: nửa trục r1 (dọc lAx), r2; thanh vuông bề dày t, k đoạn */
116	  ring(c: THREE.Vector3, nAx: THREE.Vector3, lAx: THREE.Vector3, r1: number, r2: number, t: number, k: number, bone: number, rgb: number[]): void {
117	    const s = nAx.clone().cross(lAx).normalize(), pts: THREE.Vector3[] = [], outs: THREE.Vector3[] = [];
118	    for (let i = 0; i < k; i++) { const a = 2 * Math.PI * i / k; pts.push(c.clone().addScaledVector(lAx, r1 * Math.cos(a)).addScaledVector(s, r2 * Math.sin(a))); outs.push(nAx.clone()); }
119	    this.band(pts, outs, pts.map(() => bone), t, t, rgb, true);
120	  }
121	  geometry(): THREE.BufferGeometry {
122	    const g = new THREE.BufferGeometry(), n = this.si.length;
123	    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
124	    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nor, 3));
125	    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
126	    const idx = new Uint16Array(n * 4), wt = new Float32Array(n * 4);
127	    for (let i = 0; i < n; i++) { idx[i * 4] = this.si[i]; wt[i * 4] = 1; }
128	    g.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(idx, 4));
129	    g.setAttribute('skinWeight', new THREE.Float32BufferAttribute(wt, 4));
130	    g.userData.spans = this.spans;
131	    return g;
132	  }
133	}
134	
135	/* Dựng toàn bộ trang bị quanh các vị trí nghỉ của xương */
136	export function plGearGeometry(rest: PlGearRest): THREE.BufferGeometry {
137	  const b = new GearBuf(), C = GC.colors, E = GC.round;
138	  const harness = COL(C.harness), strap = COL(C.strap), pack = COL(C.pack), toggle = COL(C.toggle), line = COL(C.line), metal = COL(C.metal), red = COL(C.reserve);
139	  const bone = { wing: BI('wing'), hang: BI('hang'), pel: BI('pelvis'), spine: BI('spine'), pack: BI('pack') };
140	  const X = V(1, 0, 0), Y = V(0, 1, 0), Z = V(0, 0, 1);
141	  const Pl = VA(rest.pelvis), S = VA(rest.spine), H = VA(rest.hang);
142	  /* hệ thân: a dọc thân (hông → Spine2), b ra trước vuông góc a trong mặt X-Y, c = +Z; tâm thân lấy z = 0 (đối xứng) */
143	  const ua = S.clone().sub(Pl); ua.z = 0; if (ua.lengthSq() < 1e-6) ua.set(0, 1, 0); ua.normalize();
144	  const fb = V(ua.y, -ua.x, 0);
145	  const T = (a: number, bb: number, c: number) => V(Pl.x, Pl.y, 0).addScaledVector(ua, a).addScaledVector(fb, bb).addScaledVector(Z, c);
146	  const G = (l: number[]) => V(Pl.x + l[0], Pl.y + l[1], l[2]);   // hệ dù so với xương hông (z tuyệt đối)
147	  const rot = (a: number) => [V(Math.cos(a), Math.sin(a), 0), V(-Math.sin(a), Math.cos(a), 0), Z.clone()];
148	
149	  /* Ghế ngồi (nghiêng theo đùi), hai má ghế, hộp dù dự phòng dưới ghế: gắn hông */
150	  const st = GC.seat, sd = GC.side, rv = GC.reserve;
151	  b.blob(G(st.c), rot(st.tilt), st.h, E, SEG.seat[0], SEG.seat[1], bone.pel, harness);
152	  for (const s of [-1, 1]) b.blob(G([sd.c[0], sd.c[1], s * sd.c[2]]), rot(st.tilt), sd.h, E, SEG.side[0], SEG.side[1], bone.pel, harness);
153	  const rc = G(rv.c);
154	  b.blob(rc, rot(st.tilt), rv.h, E, SEG.reserve[0], SEG.reserve[1], bone.pel, pack);
155	  /* quai kéo dù dự phòng: tay nắm đỏ ở mép phải hộp, dải đỏ nối vào hộp */
156	  const hp = V(rc.x + rv.handle[0], rc.y, rv.handle[1]), hd = GC.handle;
157	  b.band([V(rc.x - rv.h[0] * hd.back, rc.y + rv.h[1] * hd.up, rv.h[2] + hd.z0), V(hp.x - hd.inX, hp.y, rv.h[2] + hd.z1), hp], [Z, Z, Z], [bone.pel, bone.pel, bone.pel], hd.w, hd.t, red);
158	  b.blob(hp, [X, Y, Z], rv.handleH, hd.round, SEG.handle[0], SEG.handle[1], bone.pel, red);
159	
160	  /* Đệm thắt lưng (hông) và ba lô / tấm bảo vệ lưng (xương pack, lắc trễ nhẹ) theo hệ thân */
161	  const ax = [ua, fb, Z];
162	  b.blob(T(GC.lumbar.a, GC.lumbar.b, 0), ax, GC.lumbar.h, E, SEG.lumbar[0], SEG.lumbar[1], bone.pel, harness);
163	  b.blob(T(GC.back.a, GC.back.b, 0), ax, GC.back.h, E, SEG.back[0], SEG.back[1], bone.pack, pack);
164	
165	  /* Đai vai: sau lưng → đỉnh vai → ngực → bụng (Spine2) → carabiner (hông); carabiner, riser, dây treo */
166	  const W = GC.strapW, Tk = GC.strapT, sp = GC.shoulder, ca = GC.carabAttach;
167	  for (const s of [-1, 1]) {
168	    const c = V(H.x, H.y, s * PG.hang.half);
169	    const pts = sp.map((q) => T(q[0], q[1], s * q[2]));
170	    const outs = sp.map((q, i) => (i === 1 ? ua.clone() : fb.clone().multiplyScalar(Math.sign(q[1]) || 1)));
171	    pts.push(c.clone().add(V(ca.x, GC.carab.h * ca.shoulder, 0))); outs.push(X.clone());
172	    b.band(pts, outs, pts.map((_, i) => (i < sp.length - 1 ? bone.spine : bone.pel)), W, Tk, strap);
173	    /* đai hông: từ đáy carabiner vòng ra má ghế */
174	    b.band([c.clone().add(V(ca.x, -GC.carab.h * ca.shoulder, 0)), G([sd.c[0] + GC.sideAnchor.belt[0], sd.c[1] + sd.h[1] * GC.sideAnchor.belt[1], s * (sd.c[2] + sd.h[2])])], [X, V(0, 0, s)], [bone.pel, bone.pel], W, Tk, strap);
175	    /* carabiner: vòng bầu dục đứng trong mặt phẳng X-Y */
176	    b.ring(c, Z, Y, GC.carab.h, GC.carab.w, GC.carab.bar, SEG.carab, bone.pel, metal);
177	    /* riser: hai nhánh đai dẹt (trước / sau) từ đỉnh carabiner lên đỉnh riser (xương hang, tâm lắc) */
178	    const top = V(c.x, c.y + PG.riser, c.z);
179	    for (const dx of [-1, 1]) b.band([c.clone().add(V(dx * ca.riserDx, GC.carab.h * ca.riser, 0)), top.clone().add(V(dx * GC.riserSplit, -ca.riserDrop, 0))], [Z, Z], [bone.pel, bone.hang], GC.riserStrap[0], GC.riserStrap[1], strap);
180	    /* dây treo: lineCount dây từ đỉnh riser lên cánh */
181	    for (const t of exLineTops()) if (t.side === s) b.span('line', bone.hang, bone.wing, () => b.prism(top, V(t.x, t.y, t.z), bone.hang, bone.wing, line, GC.lineR * 2, GC.lineR * 2));
182	  }
183	  /* đai ngực nối hai đai vai + khóa giữa */
184	  const cy = GC.chestY, cs = GC.chest, sc = sp[3][2], chestB = (sp[2][1] + sp[3][1]) / 2 + Tk;
185	  for (const s of [-1, 1]) b.band([T(cy, chestB, s * sc), T(cy, chestB + cs.inset, s * cs.midZ)], [fb, fb], [bone.spine, bone.spine], W * cs.wMul, Tk, strap);
186	  b.blob(T(cy, chestB + cs.buckleUp, 0), [fb, ua, Z], GC.buckle, GC.buckleRound, SEG.buckle[0], SEG.buckle[1], bone.spine, metal);
187	
188	  /* Vòng đai đùi quanh từng đùi (vuông góc trục đùi) + khóa phía trên + đai nối lên má ghế */
189	  for (const s of [-1, 1]) {
190	    const Tg = VA(s < 0 ? rest.thighL : rest.thighR), kr = s < 0 ? rest.kneeL : rest.kneeR, Kn = kr ? VA(kr) : Tg.clone().add(V(GC.thigh.kneeFb, 0, 0));
191	    const bt = BI(s < 0 ? 'thighL' : 'thighR');
192	    const d = Kn.clone().sub(Tg).normalize(), cc = Tg.clone().lerp(Kn, GC.thigh.at);
193	    const e1 = Z.clone().cross(d).normalize(), e2 = d.clone().cross(e1).normalize();   // e1 ≈ lên, e2 ≈ ngang
194	    const pts: THREE.Vector3[] = [], outs: THREE.Vector3[] = [];
195	    for (let i = 0; i < SEG.thigh; i++) { const a = 2 * Math.PI * i / SEG.thigh, o = e1.clone().multiplyScalar(Math.cos(a)).addScaledVector(e2, Math.sin(a)); pts.push(cc.clone().addScaledVector(o, GC.thigh.r)); outs.push(o); }
196	    b.band(pts, outs, pts.map(() => bt), W, Tk, strap, true);
197	    b.blob(cc.clone().addScaledVector(e1, GC.thigh.r + GC.buckle[0]), [e1, d, e2], GC.buckle, GC.buckleRound, SEG.buckle[0], SEG.buckle[1], bt, metal);
198	    b.band([cc.clone().addScaledVector(e2, s * GC.thigh.r).addScaledVector(d, -GC.thigh.link), G([sd.c[0] + sd.h[0] * GC.sideAnchor.thigh[0], sd.c[1] + sd.h[1] * GC.sideAnchor.thigh[1], s * (sd.c[2] + sd.h[2])])], [e2.clone().multiplyScalar(s), V(0, 0, s)], [bt, bone.pel], W, Tk, strap);
199	  }
200	
201	  /* Quai phanh ×2 gắn xương bàn tay (thanh ngang lòng bàn tay, trong nắm tay); dây phanh chính từ quai lên điểm tụ (gắn cánh) rồi chia ba nhánh lên mép sau cánh */
202	  for (const s of [-1, 1]) {
203	    const hd = s < 0 ? rest.handL : rest.handR, bh = BI(s < 0 ? 'handL' : 'handR');
204	    const gp = (s < 0 ? rest.gripL : rest.gripR) ?? hd, br = (s < 0 ? rest.barL : rest.barR) ?? [0, 0, 1], fg = (s < 0 ? rest.fingL : rest.fingR) ?? [0, 1, 0];
205	    const c = VA(gp), axb = VA(br).normalize(), fd = VA(fg).normalize();
206	    b.prism(c.clone().addScaledVector(axb, -GC.toggleLen), c.clone().addScaledVector(axb, GC.toggleLen), bh, bh, toggle, GC.toggleW, GC.toggleW, fd);
207	    const tops = exBrakeTops().filter((t) => t.side === s);
208	    const tx = tops.reduce((a, t) => a + t.x, 0) / tops.length, ty = tops.reduce((a, t) => a + t.y, 0) / tops.length, tz = tops.reduce((a, t) => a + t.z, 0) / tops.length;
209	    const join = V(c.x + (tx - c.x) * GC.brakeJoin, c.y + (ty - c.y) * GC.brakeJoin, c.z + (tz - c.z) * GC.brakeJoin);
210	    b.span('brake', bh, bone.wing, () => b.prism(c, join, bh, bone.wing, line, GC.lineR * GC.brakeMul, GC.lineR * GC.brakeMul));
211	    for (const t of tops) b.prism(join, V(t.x, t.y, t.z), bone.wing, bone.wing, line, GC.lineR * GC.brakeMul, GC.lineR * GC.brakeMul);
212	  }
213	  return b.geometry();
214	}
215	
216	/* Vật liệu dùng chung: màu theo đỉnh, nhám, không kim loại để cả trang bị vẫn 1 lệnh vẽ. DoubleSide: dải đai mỏng nhìn được cả hai mặt */
217	let plGearMat: THREE.MeshStandardMaterial | null = null;
218	export function plGearMaterial(): THREE.MeshStandardMaterial {
219	  return plGearMat ??= new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.8, metalness: 0.1, side: THREE.DoubleSide });
220	}
221	
222	/* Vật mẫu để làm nóng shader trang bị (load.ts): SkinnedMesh một tam giác, vertexColors + khung xương cùng số xương, dùng đúng plGearMaterial() nên chương trình biên dịch trùng chương trình thật.
223	   Gọi xong thì dispose geometry và skeleton (vật liệu dùng chung, không dispose). Lớp 1 như trang bị thật */
224	export function plGearWarmObject(): { object: THREE.Object3D; dispose: () => void } {
225	  const g = new THREE.BufferGeometry(), n = PL_GEAR_BONES.length;
226	  g.setAttribute('position', new THREE.Float32BufferAttribute([0, 0, 0, 1, 0, 0, 0, 1, 0], 3));
227	  g.setAttribute('normal', new THREE.Float32BufferAttribute([0, 0, 1, 0, 0, 1, 0, 0, 1], 3));
228	  g.setAttribute('color', new THREE.Float32BufferAttribute([1, 1, 1, 1, 1, 1, 1, 1, 1], 3));
229	  g.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(new Uint16Array(12), 4));
230	  g.setAttribute('skinWeight', new THREE.Float32BufferAttribute([1, 0, 0, 0, 1, 0, 0, 0, 1, 0, 0, 0], 4));
231	  const m = new THREE.SkinnedMesh(g, plGearMaterial());
232	  const bones = Array.from({ length: n }, () => new THREE.Bone());
233	  for (const b of bones) m.add(b);
234	  const sk = new THREE.Skeleton(bones);
235	  m.bind(sk, new THREE.Matrix4());
236	  m.frustumCulled = false; m.castShadow = false; m.receiveShadow = false; m.layers.set(1);
237	  return { object: m, dispose: () => { g.dispose(); sk.dispose(); } };
238	}
