1	/* ===== Người treo dù: áp tư thế lên xương Bip01_* (src/explore/pilot/bones.ts) =====
2	   Mọi góc tính trong hệ C = hệ gốc bản sao nhân vật (trùng trục nhóm lắc: +X trước mặt, +Y lên, +Z bên phải người), không phụ thuộc trục cục bộ kỳ quặc của Biped:
3	   xoay R trong hệ C quanh khớp của xương b ⇒ q_b = Q_cha⁻¹ · R · Q_cha · q_b, Q_cha = hướng của xương cha trong hệ C (tích quaternion cục bộ dọc chuỗi cha).
4	   Thứ tự mỗi khung (rig.ts gọi): restore() đưa các xương do đây điều khiển về tư thế gốc → mixer.update (đoạn `sit` ghi đè xương có kênh) → apply():
5	     1) hông ngả (base.recline), 2) ba đốt sống chia đều nghiêng / chúi / vặn, 3) đầu, 4) chân (đùi, gối, bàn chân), 5) xương đòn nâng, 6) ba lô,
6	     7) cập nhật ma trận một lần, IK hai khớp cho tay tới quai phanh (đích là điểm nắm giữa lòng bàn tay, không phải cổ tay), 8) ngón co thành nắm đấm.
7	   IK tay: plTwoBone trong hệ C cho vị trí khuỷu; hướng cánh tay / cẳng tay đặt bằng ánh xạ hai trục (trục xương + trục bản lề khuỷu đo ở tư thế `sit`)
8	   nên khuỷu luôn gập đúng chiều; một phần (arm.twist) độ xoay cổ tay chia sang cẳng tay để da cổ tay không xoắn. Không cấp phát mỗi khung. */
9	import * as THREE from 'three';
10	import { CONFIG } from '../../config';
11	import { plTwoBone } from './ik';
12	import type { PlPose } from './react';
13	
14	/* Tên xương trong glb (three đổi dấu cách thành `_`; tra cả hai kiểu) */
15	const NM = (s: string): string[] => ['Bip01_' + s.replace(/ /g, '_'), 'Bip01 ' + s];
16	const REQ = ['Pelvis', 'Spine', 'Spine1', 'Spine2', 'Head', 'L UpperArm', 'L Forearm', 'L Hand', 'R UpperArm', 'R Forearm', 'R Hand', 'L Thigh', 'L Calf', 'R Thigh', 'R Calf'];
17	
18	function find(root: THREE.Object3D, s: string): THREE.Object3D | null {
19	  for (const n of NM(s)) { const o = root.getObjectByName(n); if (o) return o; }
20	  return null;
21	}
22	/* Xương bắt buộc còn thiếu (load.ts kiểm lúc nạp) */
23	export function plBonesMissing(root: THREE.Object3D): string[] { return REQ.filter((s) => !find(root, s)); }
24	
25	const _q = new THREE.Quaternion(), _q2 = new THREE.Quaternion(), _q3 = new THREE.Quaternion(), _qr = new THREE.Quaternion();
26	const _e = new THREE.Euler(), _m = new THREE.Matrix4(), _m2 = new THREE.Matrix4(), _inv = new THREE.Matrix4();
27	const _v = new THREE.Vector3(), _v2 = new THREE.Vector3(), _v3 = new THREE.Vector3();
28	const _A = new THREE.Vector3(), _W = new THREE.Vector3(), _E = new THREE.Vector3(), _g = new THREE.Vector3(), _d1 = new THREE.Vector3(), _d2 = new THREE.Vector3(), _nn = new THREE.Vector3(), _f = new THREE.Vector3(), _n = new THREE.Vector3(), _ax = new THREE.Vector3();
29	const _QU = new THREE.Quaternion(), _QF = new THREE.Quaternion(), _sh = [0, 0, 0], _wt = [0, 0, 0], _pole = [0, 0, 0];
30	const AX = new THREE.Vector3(1, 0, 0), AY = new THREE.Vector3(0, 1, 0), AZ = new THREE.Vector3(0, 0, 1);
31	const fin3 = (v: THREE.Vector3): boolean => Number.isFinite(v.x) && Number.isFinite(v.y) && Number.isFinite(v.z);
