33	/* Hai trục (a, b) → cơ sở trực chuẩn [a, b⊥, a×b⊥] ghi vào ma trận m (cột) */
34	function basis(m: THREE.Matrix4, a: THREE.Vector3, b: THREE.Vector3): THREE.Matrix4 {
35	  _v.copy(a).normalize(); _v2.copy(b).addScaledVector(_v, -b.dot(_v));
36	  if (_v2.lengthSq() < 1e-10) _v2.set(-_v.y, _v.x, 0).lengthSq() < 1e-10 ? _v2.set(0, -_v.z, _v.y) : _v2;
37	  _v2.normalize(); _v3.crossVectors(_v, _v2);
