40	/* Quaternion xoay cặp trục (a1, b1) thành (a2, b2): out = B2 · B1ᵀ */
41	function mapAxes(out: THREE.Quaternion, a1: THREE.Vector3, b1: THREE.Vector3, a2: THREE.Vector3, b2: THREE.Vector3): THREE.Quaternion {
42	  basis(_m2, a1, b1).transpose();
43	  basis(_m, a2, b2).multiply(_m2);
44	  return out.setFromRotationMatrix(_m);
