  for (const dt of [NaN, 30, -1, 1 / 60, Infinity, 0.5]) { s.bank = dt === 30 ? 9 : -9; s.pos.x += 500; s.pos.y += dt === 0.5 ? NaN : 3; exPlaceGlider(g, s, dt, { turn: 1, climb: 0, throttle: 0 }); }
