1	/* ===== Dù lượn: nhân vật người treo public/people/pilot.glb (sinh bằng scripts/people/pilot.py) — đọc phần JSON của GLB, không cần three ===== */
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { readFileSync, existsSync, statSync } from 'node:fs';
5	import { fileURLToPath } from 'node:url';
6	import { join, dirname } from 'node:path';
7	
8	const DIR = join(dirname(fileURLToPath(import.meta.url)), '../../public/people');
9	const FILE = join(DIR, 'pilot.glb');
10	const MB = 1024 * 1024;
11	// xương bắt buộc (bộ điều khiển xương của dù lượn dùng), tên gốc Rocketbox; three đổi dấu cách thành '_'
12	const BONES = ['Pelvis', 'Spine', 'Spine1', 'Spine2', 'Neck', 'Head', 'L Clavicle', 'L UpperArm', 'L Forearm', 'L Hand', 'L Thigh', 'L Calf', 'L Foot',
13	  'R Clavicle', 'R UpperArm', 'R Forearm', 'R Hand', 'R Thigh', 'R Calf', 'R Foot'].map(b => 'Bip01 ' + b);
14	const FINGERS = ['L', 'R'].flatMap(s => [0, 1, 2, 3, 4].flatMap(i => [`Bip01 ${s} Finger${i}`, `Bip01 ${s} Finger${i}1`, `Bip01 ${s} Finger${i}2`]));
15	
16	/* Đọc khối JSON đầu tiên của file GLB (header 12 byte, rồi chunk JSON) */
17	function glbJson(file: string): any {
18	  const b = readFileSync(file);
19	  assert.equal(b.readUInt32LE(0), 0x46546c67, 'không phải GLB');            // 'glTF'
20	  const len = b.readUInt32LE(12), type = b.readUInt32LE(16);
21	  assert.equal(type, 0x4e4f534a, 'chunk đầu không phải JSON');              // 'JSON'
22	  return JSON.parse(b.subarray(20, 20 + len).toString('utf8'));
23	}
24	
25	/* Số tam giác của một primitive (TRIANGLES, có hoặc không có chỉ mục) */
26	function tris(j: any, p: any): number {
27	  assert.ok(p.mode === undefined || p.mode === 4, 'primitive không phải TRIANGLES');
28	  const acc = j.accessors[p.indices ?? p.attributes.POSITION];
29	  return acc.count / 3;
30	}
31	
32	test('pilot.glb tồn tại, ≤ 2,5 MB', () => {
33	  assert.ok(existsSync(FILE), 'thiếu pilot.glb');
34	  const n = statSync(FILE).size;
35	  assert.ok(n <= 2.5 * MB, `pilot.glb ${n} byte > 2,5 MB`);
36	});
37	
38	test('pilot.glb: ≤ 25 000 tam giác, ≤ 80 khớp, ≤ 2 lưới / 2 vật liệu, không nén', () => {
39	  const j = glbJson(FILE);
40	  let t = 0;
41	  for (const m of j.meshes) for (const p of m.primitives) t += tris(j, p);
42	  assert.ok(t > 0 && t <= 25000, `${t} tam giác`);
43	  assert.equal(j.skins?.length, 1, 'phải có đúng 1 skin');
44	  const nj = j.skins[0].joints.length;
45	  assert.ok(nj >= 20 && nj <= 80, `${nj} khớp`);
46	  assert.ok(j.meshes.length <= 2, `${j.meshes.length} lưới`);
47	  assert.ok((j.materials ?? []).length <= 2, `${j.materials?.length} vật liệu`);
48	  const used: string[] = j.extensionsUsed ?? [];
49	  assert.ok(!used.includes('KHR_draco_mesh_compression') && !used.includes('EXT_meshopt_compression'), 'không dùng Draco / Meshopt');
50	});
51	
52	test('pilot.glb: đoạn sit dài 3–7 s', () => {
53	  const j = glbJson(FILE);
54	  const a = (j.animations ?? []).find((x: any) => x.name === 'sit');
55	  assert.ok(a, 'thiếu đoạn sit');
56	  let dur = 0;
57	  for (const s of a.samplers) dur = Math.max(dur, j.accessors[s.input].max?.[0] ?? 0);
58	  assert.ok(dur >= 3 && dur <= 7, `sit dài ${dur} s`);
59	});
60	
61	/* Đọc accessor float (không stride) từ chunk BIN của GLB */
62	function floats(file: string, j: any, i: number): { n: number; count: number; d: Float32Array } {
63	  const b = readFileSync(file), len = b.readUInt32LE(12), bin = 20 + len + 8;
64	  const a = j.accessors[i], v = j.bufferViews[a.bufferView];
65	  assert.equal(a.componentType, 5126, `accessor ${i} không phải float`);
66	  assert.ok(!v.byteStride, `accessor ${i} có byteStride`);
67	  const n = ({ SCALAR: 1, VEC3: 3, VEC4: 4 } as Record<string, number>)[a.type];
68	  const off = bin + (v.byteOffset ?? 0) + (a.byteOffset ?? 0);
69	  return { n, count: a.count, d: new Float32Array(b.buffer.slice(b.byteOffset + off, b.byteOffset + off + a.count * n * 4)) };
70	}
71	
72	// Khép vòng sit: khung đầu và khung cuối mỗi kênh xoay lệch ≤ 0,1° (bản sinh ngày 2026-11-13 lệch tối đa ≈ 0,035°)
73	const LOOP_DEG = 0.1;
74	
75	test('pilot.glb: sit không diễn ngón tay, hông đứng yên, khép vòng', () => {
76	  const j = glbJson(FILE);
77	  const a = j.animations.find((x: any) => x.name === 'sit');
78	  let rot = 0;
79	  for (const ch of a.channels) {
80	    const name: string = j.nodes[ch.target.node].name ?? '';
81	    assert.ok(!name.includes('Finger'), `kênh ${ch.target.path} của ngón ${name}`);
82	    const o = floats(FILE, j, a.samplers[ch.sampler].output);
83	    if (/Pelvis$/.test(name) && ch.target.path === 'translation')
84	      for (let k = 0; k < o.count; k++) for (let q = 0; q < 3; q++)
85	        assert.ok(Math.abs(o.d[k * 3 + q] - o.d[q]) <= 1e-4, `hông dời ở khung ${k}: ${o.d[k * 3 + q]} so với ${o.d[q]}`);
86	    if (ch.target.path === 'rotation') {
87	      rot++;
88	      const z = (o.count - 1) * 4;
89	      const dot = Math.abs(o.d[0] * o.d[z] + o.d[1] * o.d[z + 1] + o.d[2] * o.d[z + 2] + o.d[3] * o.d[z + 3]);
90	      const deg = 2 * Math.acos(Math.min(1, dot)) * 180 / Math.PI;
91	      assert.ok(deg <= LOOP_DEG, `${name}: khung đầu / cuối lệch ${deg.toFixed(3)}° > ${LOOP_DEG}°`);
92	    }
93	  }
94	  assert.ok(rot >= 20, `chỉ ${rot} kênh xoay`);
95	});
96	
97	test('pilot.glb: không có vũ khí (dao, súng)', () => {
98	  const j = glbJson(FILE);
99	  const bad = /knife|pistol|weapon|gun/i;
100	  for (const k of ['nodes', 'meshes', 'materials', 'images', 'textures']) for (const x of j[k] ?? []) assert.ok(!bad.test(x.name ?? ''), `${k}: ${x.name}`);
101	});
102	
103	test('pilot.glb: đủ xương bắt buộc (thân, tay, chân, ngón)', () => {
104	  const j = glbJson(FILE);
105	  const names = new Set(j.nodes.map((n: any) => n.name));
106	  for (const b of [...BONES, ...FINGERS]) assert.ok(names.has(b) || names.has(b.replace(/ /g, '_')), `thiếu xương ${b}`);
107	});
108	
109	test('pilot.glb: extras height, hip (m)', () => {
110	  const j = glbJson(FILE);
111	  const e = j.scenes?.[0]?.extras ?? {};
112	  assert.equal(typeof e.height, 'number', 'thiếu height');
113	  assert.ok(e.height > 1.5 && e.height < 2.1, `height ${e.height}`);
114	  assert.equal(typeof e.hip, 'number', 'thiếu hip');
115	  assert.ok(e.hip > 0.8 && e.hip < e.height, `hip ${e.hip}`);
116	});
117	
118	test('LICENSE-Rocketbox.txt ghi pilot.glb và Military_Male_01', () => {
119	  const t = readFileSync(join(DIR, 'LICENSE-Rocketbox.txt'), 'utf8');
120	  assert.match(t, /pilot\.glb/);
121	  assert.match(t, /Military_Male_01/);
122	  assert.match(t, /MIT/);
123	});
